import os
import re
import sys
from pathlib import Path

ROOT = Path(os.environ.get('TESTBED_ROOT', '/testbed'))
SKIP_DIRS = {'.git', '.hg', '.svn', '__pycache__', 'node_modules', 'venv', '.venv', 'dist', 'build', '.tox', '.mypy_cache', '.pytest_cache'}

def main():
    try:
        data = json.load(sys.stdin)
    except Exception:
        print(json.dumps({'content': 'Error: invalid input JSON.'}, ensure_ascii=False))
        return
    params = (data.get('parameters') or {}) if isinstance(data, dict) else {}
    pattern = params.get('pattern')
    if not isinstance(pattern, str) or not pattern.strip():
        print(json.dumps({'content': 'Error: pattern is required.'}, ensure_ascii=False))
        return
    include = str(params.get('include', '*.py'))
    includes = [item.strip() for item in include.split(',') if item.strip()]
    if not includes:
        includes = ['*.py']
    try:
        max_matches = int(params.get('max_matches', 200))
    except (TypeError, ValueError):
        max_matches = 200
    max_matches = max(1, min(max_matches, 1000))
    case_sensitive = bool(params.get('case_sensitive', True))
    flags = 0 if case_sensitive else re.IGNORECASE
    try:
        rx = re.compile(pattern, flags)
    except re.error as exc:
        print(json.dumps({'content': 'Error: invalid regular expression: %s' % exc}, ensure_ascii=False))
        return

    matches = []
    truncated = False
    for root, dirs, files in os.walk(ROOT):
        dirs[:] = sorted(d for d in dirs if d not in SKIP_DIRS and not d.startswith('.'))
        for name in sorted(files):
            path = Path(root) / name
            if not any(path.match(inc) for inc in includes):
                continue
            try:
                with open(path, 'rb') as fh:
                    if 0 in fh.read(8192):
                        continue
                with open(path, 'r', encoding='utf-8', errors='ignore') as fh:
                    for line_no, line in enumerate(fh, 1):
                        if rx.search(line):
                            matches.append({
                                'path': str(path),
                                'line': line_no,
                                'text': line.rstrip()[:300],
                            })
                            if len(matches) >= max_matches:
                                truncated = True
                                break
                    if truncated:
                        break
            except (OSError, UnicodeDecodeError):
                continue
        if truncated:
            break

    content = chr(10).join('%s:%d: %s' % (m['path'], m['line'], m['text']) for m in matches)
    if not content:
        content = 'No matches found.'
    details = {
        'pattern': pattern,
        'include': includes,
        'match_count': len(matches),
        'truncated': truncated,
        'matches': matches,
    }
    print(json.dumps({'content': content, 'details': details}, ensure_ascii=False))

if __name__ == '__main__':
    main()",
